import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useLocation, useNavigate } from 'react-router-dom';

// --- NAVBAR (Logic dyal display name) ---
const Navbar = ({ cartCount }) => {
  const location = useLocation();
  const isActive = (path) => location.pathname === path;
  const user = localStorage.getItem('username');

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/login";
  };

  return (
    <nav className="bg-white/95 backdrop-blur-md sticky top-0 z-50 w-full border-b border-gray-100 shadow-sm">
      <div className="max-w-7xl mx-auto px-6 h-20 flex justify-between items-center">
        <Link to="/" className="flex items-center space-x-3 text-gray-900 font-black text-xl uppercase italic">
           Fast<span className="text-orange-600">Délice</span>
        </Link>

        <div className="flex items-center space-x-4">
          {user ? (
            <div className="flex items-center space-x-4">
              <span className="text-[11px] font-black uppercase text-orange-600 italic">Salut, {user}</span>
              <button onClick={handleLogout} className="text-red-600 text-[10px] font-black uppercase hover:underline transition">Quitter</button>
            </div>
          ) : (
            <div className="flex space-x-4">
              <Link to="/register" className="text-gray-900 text-[11px] font-black uppercase">S'inscrire</Link>
              <Link to="/login" className="bg-orange-600 text-white px-5 py-2.5 rounded-full text-[11px] font-black uppercase">Connexion</Link>
            </div>
          )}
        </div>
      </div>
    </nav>
  );
};

// --- REGISTER (Fix Erreur d'inscription) ---
const Register = () => {
  const [formData, setFormData] = useState({ username: '', email: '', password: '' });
  const [error, setError] = useState("");
  const navigate = useNavigate();

  const handleRegister = async (e) => {
    e.preventDefault();
    setError("");
    try {
      // Sifti ga3 l-data o t-akdi annaha s-7i7a f l-backend
      await axios.post('http://127.0.0.1:8000/api/register/', formData);
      navigate('/login');
    } catch (err) {
      setError("❌ Erreur d'inscription. L-user imken deja m-kriyi awla l-backend fih mochkil.");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-black/50">
      <div className="max-w-md w-full bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl">
        {error && <p className="mb-6 text-center text-red-400 font-bold text-sm italic">{error}</p>}
        <form className="space-y-6" onSubmit={handleRegister}>
          <input type="text" placeholder="NOM COMPLET" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setFormData({...formData, username: e.target.value})} />
          <input type="email" placeholder="EMAIL" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setFormData({...formData, email: e.target.value})} />
          <input type="password" placeholder="MOT DE PASSE" required className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" onChange={(e) => setFormData({...formData, password: e.target.value})} />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition">S'inscrire Now</button>
        </form>
      </div>
    </div>
  );
};

// --- LOGIN (Fix Identifiants incorrects) ---
const Login = () => {
  const [formData, setFormData] = useState({ username: '', password: '' });
  const [error, setError] = useState("");

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    try {
      // Hna l-backend dima kiy-tsenna key smiyto "username"
      const res = await axios.post('http://127.0.0.1:8000/api/login/', formData);

      // I-la t-la3 success, khbbi l-data
      localStorage.setItem('username', res.data.username || formData.username.split('@')[0]);
      localStorage.setItem('token', res.data.token);

      window.location.href = "/"; 
    } catch (err) {
      setError("❌ Identifiants incorrects. Checki l-email/password dyalk.");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-black/50">
      <div className="max-w-md w-full bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] shadow-2xl text-center">
        <h2 className="text-white text-5xl font-black italic uppercase mb-8 tracking-tighter">Connexion</h2>
        {error && <p className="mb-6 text-red-400 font-bold text-sm italic">{error}</p>}
        <form className="space-y-6" onSubmit={handleLogin}>
          <input 
            type="text" 
            placeholder="VOTRE EMAIL" 
            required 
            className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" 
            onChange={(e) => setFormData({...formData, username: e.target.value})} 
          />
          <input 
            type="password" 
            placeholder="MOT DE PASSE" 
            required 
            className="w-full bg-white/5 border border-white/10 rounded-2xl py-4 px-6 text-white outline-none focus:border-orange-600 transition font-bold" 
            onChange={(e) => setFormData({...formData, password: e.target.value})} 
          />
          <button type="submit" className="w-full bg-orange-600 text-white py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-white hover:text-black transition">Se Connecter</button>
        </form>
      </div>
    </div>
  );
};

export default function App() {
  return (
    <Router>
      <div className="min-h-screen bg-black">
        <Navbar cartCount={0} />
        <Routes>
          <Route path="/register" element={<Register />} />
          <Route path="/login" element={<Login />} />
          <Route path="/" element={<div className="text-white text-center py-20 text-4xl font-black italic">BIENVENUE CHEZ FAST DÉLICE</div>} />
        </Routes>
      </div>
    </Router>
  );
}
